-- Applied live: 34 questions (#17808-#17841, imported Oct 28) had no rationale; each now explains the key.
-- Only rows whose rationale is still empty are updated.
UPDATE test_questions SET rationale = $rat$Increasing fluids (a) flushes the urinary tract and lowers the risk of urinary tract infection (UTI), and hand hygiene (e) is the single most effective way to stop staff from spreading organisms to residents. Standardizing diuretic times does not prevent infection, reminders for turning prevent pressure injuries rather than UTIs, and bathing in shared basins can carry bacteria from one area to another.$rat$ WHERE id = 17808 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Pinworms migrate to the perianal skin at night to lay eggs, which causes intense perianal itching and disturbed sleep. Constipation, ribbon-like stools and fever are not features of enterobiasis (pinworm infection).$rat$ WHERE id = 17809 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$A vegan diet excludes all animal products, so plant foods such as legumes, tofu, almonds, prunes and grapefruit are appropriate. Baked fish is an animal product and should not be recommended.$rat$ WHERE id = 17810 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$High-fiber choices come from whole grains, legumes and vegetables: bran muffins, kidney beans, brown rice, whole wheat pasta and corn all add fiber and help prevent constipation in pregnancy. French fries are low in fiber and high in fat.$rat$ WHERE id = 17811 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$For Ebola virus disease (EVD), limiting visitors, logging every health care worker who enters and leaves, and having a trained observer watch donning and doffing of personal protective equipment all reduce exposure. Bleach-based disinfectant wipes are used to clean surfaces. Personal protective equipment must be single-use and disposed of safely, so reusable equipment is not appropriate.$rat$ WHERE id = 17812 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Testing is recommended for all of these situations: pregnancy (to prevent transmission to the baby), sex work, a current sexually transmitted infection, injection drug use, and men who have sex with men (MSM), because each carries a higher risk of exposure to the human immunodeficiency virus (HIV).$rat$ WHERE id = 17813 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Findings that need follow-up are a blood glucose of 266 mg/dL on dextrose (hyperglycemia raises the risk of surgical complications), abdominal shaving (it causes skin nicks that raise infection risk; clipping is preferred), a history of a very high fever with a previous surgery (possible malignant hyperthermia, which is a serious anesthesia risk), and burning with urination and frequency (a possible urinary tract infection, which may delay surgery). Taking carbamazepine with a sip of water is usually allowed before surgery.$rat$ WHERE id = 17814 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Electroconvulsive therapy (ECT) uses a brief electrical stimulus under anesthesia and a muscle relaxant. No contrast dye is given, so that statement needs correcting. Clients are drowsy and may be confused afterward, so they must not drive, and ECT is given as a series of treatments (often 6 to 12), not one. Taking essential morning medications with a sip of water and expecting temporary confusion and memory loss are accurate statements.$rat$ WHERE id = 17815 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Uncontrolled pain activates the sympathetic stress response, which causes tachypnea, nausea, mydriasis (dilated pupils) and increased blood glucose. Pain raises the heart rate, so bradycardia is not expected.$rat$ WHERE id = 17816 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$The creatinine of 2.1 mg/dL and blood urea nitrogen (BUN) of 25 mg/dL show reduced kidney function. Vancomycin is nephrotoxic and its dose must be adjusted, furosemide can worsen dehydration and kidney injury, and ketorolac (a nonsteroidal anti-inflammatory drug) is nephrotoxic and should be avoided. A saline bolus supports kidney perfusion, and diltiazem is not a kidney concern, so those orders do not need clarification.$rat$ WHERE id = 17817 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Diltiazem (a calcium channel blocker) controls the heart rate in atrial fibrillation, and warfarin lowers the stroke risk from clots that form in the fibrillating atria. Nitroglycerin treats angina, clonidine treats hypertension and atorvastatin lowers cholesterol, so none of these treats the rhythm or its clot risk.$rat$ WHERE id = 17818 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$A burn over 25% of the body surface area needs the client to stay nothing by mouth (NPO) because of the risk of paralytic ileus and the need for resuscitation. A 12-lead electrocardiogram checks for dysrhythmias from tissue injury and electrolyte shifts, and arterial blood gases assess oxygenation and acid-base status. Hypertonic saline is not used for fluid resuscitation, and burns are not irrigated with chlorhexidine; a topical antimicrobial such as silver sulfadiazine is used instead.$rat$ WHERE id = 17819 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$In status epilepticus the priorities are to call for help early (notify the rapid response team), get an order for lorazepam, the first-line drug to stop the seizure, and loosen restrictive clothing to protect the airway and breathing. Oral carbamazepine cannot be given during a seizure, and reviewing a phenytoin level can wait until the seizure is controlled.$rat$ WHERE id = 17820 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$The head of the bed must be raised to at least 30 to 45 degrees during tube feeding and medication to prevent aspiration, so 15 degrees needs correction. Crushed medications must never be added directly to the tube feeding; each is given separately and the tube is flushed between them. Giving drugs separately, verifying tube placement and crushing each tablet into a fine powder are correct.$rat$ WHERE id = 17821 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Celiac disease damages the small intestine when gluten is eaten, which causes malabsorption, so fatty, foul-smelling stools (steatorrhea) and malnutrition are expected. Bilious vomiting suggests an obstruction, joint pain is not a typical sign, and a sausage-shaped abdominal mass suggests intussusception.$rat$ WHERE id = 17822 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$In hemophilia, bleeding into the joints (hemarthrosis) causes joint pain and decreased range of motion, and bleeding from mucous membranes and the urinary tract causes epistaxis (nosebleeds) and hematuria. Splenomegaly is not a feature of hemophilia.$rat$ WHERE id = 17823 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$At 9 months an infant is expected to sit without support and roll over. Standing alone, taking first steps and walking unsupported develop closer to 12 months and later.$rat$ WHERE id = 17824 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$A palpable, solid, elevated lesion about 1 cm across is described as a nodule, or as a plaque when it is a broader raised lesion of 1 cm or more. Macules and patches are flat and not palpable, a bulla is a large fluid-filled blister, and a pustule is a pus-filled lesion.$rat$ WHERE id = 17825 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Rubella, pharyngeal diphtheria and Haemophilus influenzae type b spread by large respiratory droplets, so these clients need droplet precautions. Pulmonary tuberculosis requires airborne precautions, and a client with a chemotherapy port or a Klebsiella skin abscess does not need droplet precautions.$rat$ WHERE id = 17826 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Pheochromocytoma is an adrenal tumor that releases excess catecholamines, which raises blood glucose, so a statement that glucose will decrease needs correction. Energy drinks contain stimulants that can trigger a hypertensive crisis and should be avoided. Diuretics are not given because these clients are often volume depleted and prone to orthostatic hypotension. Reducing stress and monitoring blood pressure are appropriate.$rat$ WHERE id = 17827 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Looking at a co-worker's or friend's record for a personal reason, even with permission or as a listed power of attorney, is a privacy violation, because access is only for assigned care. Leaving a terminal unsecured also exposes client information. Reviewing prescriptions with a student nurse who is assigned to the client is part of care and is allowed.$rat$ WHERE id = 17828 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Neural tube defects include spina bifida occulta, spina bifida cystica, meningocele and myelomeningocele, and an exposed sac is protected with a sterile, moist, non-adherent dressing. The infant is usually kept prone to keep pressure off the sac, so left-lateral is not the optimal position. Deficits are not always present (for example in spina bifida occulta), and folic acid, not vitamin D, helps prevent these defects.$rat$ WHERE id = 17829 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Hydrocephalus is a buildup of cerebrospinal fluid that raises intracranial pressure, which causes an enlarging head, a full or bulging fontanel, a downward gaze (setting-sun eyes) and vomiting. A sunken anterior fontanel is a sign of dehydration, not increased pressure.$rat$ WHERE id = 17830 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Parents should tell the children honestly, reassure them physically and emotionally, and expect that children may react with resentment or anger. Parents do not need to hide their own emotions, and the topic should not be limited or avoided, because children need open communication.$rat$ WHERE id = 17831 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Burning with urination suggests a urinary tract infection, which needs treatment in pregnancy, and decreased appetite is unexpected because appetite usually increases and may point to nausea, illness or poor nutrition. A third heart sound, dependent edema, absence of menstruation and breast tenderness are common, expected findings in pregnancy.$rat$ WHERE id = 17832 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$A clear liquid diet includes foods that are clear and liquid at body temperature: apple juice, fat-free bouillon, clear hard candy, gelatin and hot tea with sugar. Sherbet, pudding, yogurt, coffee with milk and tomato juice are not clear liquids.$rat$ WHERE id = 17833 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Lifestyle changes that lower blood pressure include regular exercise (including isometric handgrip training), reducing sodium, stopping smoking and losing weight. Herbal supplements are not recommended because they can raise blood pressure or interact with antihypertensive drugs.$rat$ WHERE id = 17834 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Chorioamnionitis is an infection of the membranes and amniotic fluid, so findings include uterine tenderness and maternal fever, along with maternal and fetal tachycardia. Proteinuria suggests preeclampsia, painless bright red bleeding suggests placenta previa, and fetal bradycardia is not expected because the fetal heart rate rises.$rat$ WHERE id = 17835 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$The drainage bag should be emptied when it is about half full, and the tubing should be secured to the linens so it does not pull on the catheter. Cleaning the catheter is done from the meatus downward while holding it securely. Perineal care uses mild soap and warm water, not hot, and clean gloves are used for hygiene, not sterile ones.$rat$ WHERE id = 17836 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Frostbite is treated with rapid rewarming in a water bath at 99 to 102 degrees F (37 to 39 degrees C), a tetanus immunization, analgesics, and reporting increasing pain after medication because it may signal compartment syndrome, which is checked hourly. Massage and dry heat can cause further tissue damage and should not be used.$rat$ WHERE id = 17837 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Repeating numbers individually (for example, 'one-five' rather than 'fifteen') prevents mix-ups, and verbal or telephone orders should be limited to emergencies. Unlicensed assistive personnel (UAP) cannot take orders, more abbreviations increase errors, and delaying transcription for a second nurse is unnecessary and unsafe.$rat$ WHERE id = 17838 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$Mania produces impulsivity, an expansive (elevated, grandiose) mood, tangential speech and hypersexuality. Lethargy is a feature of depression, and appetite is usually decreased, not increased, during mania.$rat$ WHERE id = 17839 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$In disaster triage, intensive care unit (ICU) resources go to clients who need them and have a good chance of survival: a flail chest requiring intubation, septic shock that is responding to treatment, and a traumatic brain injury with rising intracranial pressure. A Glasgow Coma Scale score of 3 with fixed pupils and burns over 85% of the body carry a very poor chance of survival, and an open leg fracture with stable vital signs does not need ICU care.$rat$ WHERE id = 17840 AND (rationale IS NULL OR length(trim(rationale)) = 0);
UPDATE test_questions SET rationale = $rat$A newborn is secured in a rear-facing seat in the back, with harness straps at or below the shoulders, snug, the chest clip at armpit level, and the recline indicator showing the correct semi-reclined position so the airway stays open. Nothing, including cushions or blankets, should go between the baby and the harness, the seat must not move more than 1 inch at the belt path, and children stay rear-facing until they reach the seat's limits, well beyond 12 months.$rat$ WHERE id = 17841 AND (rationale IS NULL OR length(trim(rationale)) = 0);
